// lib/report/fonts.ts
// Rejestracja fontów dla @react-pdf/renderer. Wspólne dla wszystkich dokumentów.
// Fonty wbudowane jako base64 — działa na Vercel serverless bez HTTP i plików.

import { Font } from "@react-pdf/renderer";

const LATO_REGULAR = "data:font/truetype;base64,";
const LATO_BOLD    = "data:font/truetype;base64,";

Font.register({
  family: "Lato",
  fonts: [
    { src: LATO_REGULAR },
    { src: LATO_BOLD, fontWeight: 700 },
  ],
});
